import{_ as i,C as l,o as d,c,ag as n,E as s,w as a,a as t,j as r}from"./chunks/framework.BSwSpTvy.js";const b=JSON.parse('{"title":"⚡ Tool: context","description":"","frontmatter":{},"headers":[],"relativePath":"features/tools/context.md","filePath":"features/tools/context.md"}'),m={name:"features/tools/context.md"};function p(u,e,h,g,f,x){const o=l("ZedChat");return d(),c("div",null,[e[6]||(e[6]=n('<h1 id="⚡-tool-context" tabindex="-1">⚡ Tool: <code>context</code> <a class="header-anchor" href="#⚡-tool-context" aria-label="Permalink to &quot;⚡ Tool: `context`&quot;">​</a></h1><p>The <code>context</code> tool is the interface between the AI agent and your project&#39;s <strong>Language Server Protocol (LSP)</strong>. It provides 100% accurate, compiler-verified code definitions.</p><h2 id="technical-implementation" tabindex="-1">Technical Implementation <a class="header-anchor" href="#technical-implementation" aria-label="Permalink to &quot;Technical Implementation&quot;">​</a></h2><p>Standard Zed utilizes a background regex-based semantic indexer. This fork disables that subsystem and replaces it with <code>crates/agent/src/tools/context_tool.rs</code>.</p><p>When the agent needs to understand a symbol, it forwards the request directly to the active server (<code>rust-analyzer</code>, <code>pyright</code>, etc.). This ensures the agent is reading the <strong>actual resolved AST</strong> of your project, not just a text-based guess.</p><h2 id="usage-examples" tabindex="-1">Usage Examples <a class="header-anchor" href="#usage-examples" aria-label="Permalink to &quot;Usage Examples&quot;">​</a></h2><h3 id="example-1-locating-type-definitions" tabindex="-1">Example 1: Locating Type Definitions <a class="header-anchor" href="#example-1-locating-type-definitions" aria-label="Permalink to &quot;Example 1: Locating Type Definitions&quot;">​</a></h3>',7)),s(o,null,{user:a(()=>[...e[0]||(e[0]=[t(" Where is the `spawn` method defined in the GPUI crate? ",-1)])]),assistant:a(()=>[...e[1]||(e[1]=[t(" Querying LSP for `spawn` definition... ",-1)])]),output:a(()=>[...e[2]||(e[2]=[t(' @context({ query: "spawn" }) >> Found: crates/gpui/src/executor.rs:L112 ',-1)])]),_:1}),e[7]||(e[7]=r("h3",{id:"example-2-understanding-trait-implementations",tabindex:"-1"},[t("Example 2: Understanding Trait Implementations "),r("a",{class:"header-anchor",href:"#example-2-understanding-trait-implementations","aria-label":'Permalink to "Example 2: Understanding Trait Implementations"'},"​")],-1)),s(o,null,{user:a(()=>[...e[3]||(e[3]=[t(" Show me all implementations of the `Render` trait for components in `crates/ui`. ",-1)])]),assistant:a(()=>[...e[4]||(e[4]=[t(" Requesting LSP implementation map for `Render` trait... ",-1)])]),output:a(()=>[...e[5]||(e[5]=[t(' @context({ query: "Render" }) >> Impl 1: crates/ui/src/button.rs >> Impl 2: crates/ui/src/modal.rs ',-1)])]),_:1}),e[8]||(e[8]=n('<h2 id="workflow-impact-impact" tabindex="-1">Workflow Impact &amp; Impact <a class="header-anchor" href="#workflow-impact-impact" aria-label="Permalink to &quot;Workflow Impact &amp; Impact&quot;">​</a></h2><ul><li><strong>Zero Hallucination</strong>: The agent sees exactly what the compiler sees. It never guesses a file path or a symbol location.</li><li><strong>Contextual Precision</strong>: Understands the difference between <code>model.save()</code> and <code>result.save()</code> even if they share the same method name.</li><li><strong>Zero-Config Performance</strong>: Works instantly with your existing LSP setup (<code>rust-analyzer</code>, <code>gopls</code>, etc.) without needing a background index.</li><li><strong>Massive Scale</strong>: Can find a needle in a haystack across 1M+ lines of code by offloading the heavy lifting to the Language Server.</li></ul>',2))])}const y=i(m,[["render",p]]);export{b as __pageData,y as default};
